ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
    "jsonrpc": "2.0",
    "id": vars.requestId,
    "result": {
        "tools": [
            {
                "name": "get_current_time",
                "description": "Get the current date and time for a city or timezone. Returns formatted local time with timezone abbreviation.",
                "inputSchema": {
                    "type": "object",
                    "properties": {
                        "city": {
                            "type": "string",
                            "description": "City name (e.g., 'Tokyo', 'New York', 'London') or IANA timezone ID (e.g., 'America/New_York')"
                        }
                    },
                    "required": ["city"]
                }
            },
            {
                "name": "convert_time",
                "description": "Convert a specific time from one timezone to another. Useful for scheduling meetings across timezones.",
                "inputSchema": {
                    "type": "object",
                    "properties": {
                        "time": {
                            "type": "string",
                            "description": "Time to convert in HH:mm format (24-hour) e.g., '14:30' or '09:00'"
                        },
                        "from_city": {
                            "type": "string",
                            "description": "Source city or timezone (e.g., 'New York', 'Asia/Tokyo')"
                        },
                        "to_city": {
                            "type": "string",
                            "description": "Target city or timezone (e.g., 'London', 'Europe/Paris')"
                        }
                    },
                    "required": ["time", "from_city", "to_city"]
                }
            },
            {
                "name": "time_difference",
                "description": "Get the time difference in hours between two cities. Shows which city is ahead and by how many hours.",
                "inputSchema": {
                    "type": "object",
                    "properties": {
                        "city1": {
                            "type": "string",
                            "description": "First city or timezone (e.g., 'New York', 'America/Chicago')"
                        },
                        "city2": {
                            "type": "string",
                            "description": "Second city or timezone (e.g., 'Tokyo', 'Asia/Kolkata')"
                        }
                    },
                    "required": ["city1", "city2"]
                }
            },
            {
                "name": "list_timezones",
                "description": "List available timezones, optionally filtered by region. Regions include: America, Europe, Asia, Africa, Australia, Pacific.",
                "inputSchema": {
                    "type": "object",
                    "properties": {
                        "region": {
                            "type": "string",
                            "description": "Optional region filter (e.g., 'Asia', 'Europe', 'America', 'Africa'). If omitted, returns all supported cities."
                        }
                    },
                    "required": []
                }
            }
        ]
    }
}
